enum fetch_step
handle_backend_fetch_failure(struct worker *wrk, struct busyobj *bo) {
    if (wrk == NULL || bo == NULL)
        return F_STP_FAIL;

    wrk->fetch_failure_count++;

    // Setup HTTP response for backend fetch failure
    HTTP_SetHeader(bo->http, "Backend-Fetch-Failure", "true", 0);
    HTTP_SetHeader(bo->http, "Content-Type", "text/html", 0);

    // Setup TTL and grace periods based on waiting list status
    if (bo->waitinglist != NULL) {
        bo->objcore->ttl = 0;
        bo->objcore->grace = 0;
    }

    // Create synthetic body for the error response
    const char *error_body = "<html><body><h1>Backend Fetch Failure</h1></body></html>";
    bo->body_len = strlen(error_body);
    bo->do_stream = 0;
    bo->doclose = SC_CLOSE;

    // Invoke VCL method for backend error handling
    // Assuming a VCL function named vcl_backend_error exists
    vcl_backend_error(wrk, bo);

    // Determine next step based on worker handling state
    if (wrk->handling == VH_RETRY) {
        return F_STP_RETRY;
    } else if (wrk->handling == VH_DELIVER) {
        return F_STP_DONE;
    } else {
        return F_STP_FAIL;
    }
}

enum fetch_step
handle_backend_fetch_failure(struct worker *wrk, struct busyobj *bo)
{
	(void)wrk;
	(void)bo;

	if (wrk == NULL || bo == NULL)
		return (F_STP_FAIL);

	bo->fetch_failed++;

	VSLb(bo->vsl, SLT_FetchError, "Backend fetch failed");

	if (bo->objcore != NULL) {
		bo->objcore->t_ttl = 0.0;
		bo->objcore->t_grace = 0.0;
		if (bo->objcore->waitinglist != NULL)
			bo->objcore->t_lru = 0.0;
	}

	bo->http[HTTP_HDR_STATUS] = HTTP_Copy("502");
	HTTP_SetHdr(bo->http, H_Reason, "Backend Fetch Failed", NULL);

	if (vbe_make_synthetic_body(wrk, bo) != 0)
		return (F_STP_FAIL);

	VCL_call_method(wrk, VCL_MET_BackendError, bo);

	if (bo->do_retry) {
		bo->do_retry = 0;
		return (F_STP_RETRY);
	}

	if (bo->do_pass) {
		bo->do_pass = 0;
		return (F_STP_DONE);
	}

	bo->do_esi = 0;
	bo->do_gunzip = 0;

	return (F_STP_FAIL);
}

enum fetch_step
handle_backend_fetch_failure(struct worker *wrk, struct busyobj *bo)
{
    if (wrk == NULL || bo == NULL)
        return (F_STP_FAIL);

    /* Increment fetch failure count */
    if (atomic_fetch_add_explicit(&bo->fetch_failure_count, 1, memory_order_relaxed) >= MAX_FETCH_RETRIES)
        return (F_STP_FAIL);

    /* Set up HTTP response for backend fetch failure */
    http_set_status(bo->http, 502);
    http_set_header(bo->http, "Content-Type", "text/plain");
    http_set_header(bo->http, "Content-Length", "0");
    http_set_header(bo->http, "X-Backend-Failure", "1");

    /* Manage TTL and grace periods based on waiting list status */
    if (bo->waiting_list != NULL) {
        bo->objcore->ttl = TTL_GRACE;
        bo->objcore->grace = TTL_GRACE;
    } else {
        bo->objcore->ttl = TTL_NORMAL;
        bo->objcore->grace = 0;
    }

    /* Create synthetic body for error response */
    if (bo->http->bodylen == 0)
        http_set_body(bo->http, "Backend fetch failed.");

    /* Call VCL method for backend error handling */
    if (vcl_backend_error(wrk, bo) != VCL_RET_RETRY)
        return (F_STP_DONE);

    /* Store the synthetic response */
    if (store_object(wrk, bo) == 0) {
        bo->objcore->flags |= OC_F_SYNTHETIC;
        return (F_STP_RETRY);
    }

    return (F_STP_FAIL);
}

